import org.eclipse.rdf4j.model.util.Values;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.QueryBindingSet;
import org.junit.jupiter.api.Test;

class FilteringInsertBindingsIterationTest {

	@Test
	void filterSeesInputAndResultRowWithRowTakingPrecedence() {
		FilterExpr filter = new FilterExpr(Var.of("row"), new HashSet<>(Set.of("row")));
		FederationEvaluationStrategy strategy = mock(FederationEvaluationStrategy.class);
		when(strategy.isTrue(same(filter), any(BindingSet.class))).thenAnswer(invocation -> {
			BindingSet row = invocation.getArgument(1);
			return Values.literal("input").equals(row.getValue("entry"))
					&& Values.literal("match").equals(row.getValue("shared"));
		});
		QueryBindingSet input = new QueryBindingSet();
		input.addBinding("entry", Values.literal("input"));
		input.addBinding("shared", Values.literal("old"));
		QueryBindingSet match = new QueryBindingSet();
		match.addBinding("shared", Values.literal("match"));
		QueryBindingSet miss = new QueryBindingSet();
		miss.addBinding("shared", Values.literal("miss"));

		try (var iteration = new FilteringInsertBindingsIteration(filter, input,
				new CloseableIteratorIteration<>(List.<BindingSet>of(match, miss).iterator()), strategy)) {
			assertTrue(iteration.hasNext());
			BindingSet result = iteration.next();
			assertEquals(Values.literal("input"), result.getValue("entry"));
			assertEquals(Values.literal("match"), result.getValue("shared"));
			assertFalse(iteration.hasNext());
		}
	}
}
